# Подсказки к терминам: глоссарий (14_glossary.md) + русские термины ниже.
# Каждая запись: (паттерны regex, заголовок, объяснение). Паттерны ищутся без учёта регистра, целыми словами.
import re
from abbr import enrich

OVR = {
 'AFFO — Adjusted FFO': 'AFFO — Adjusted Funds From Operations',
 'PPA — Power Purchase Agreement': 'PPA — Power Purchase Agreement',
 'ESOP — Employee Stock Option Plan': 'ESOP — Employee Stock Option Plan',
 'MoM / MOIC — Multiple of Money / Multiple on Invested Capital': 'MoM / MOIC — Multiple of Money / Multiple on Invested Capital',
 'MIRR — Modified IRR': 'MIRR — Modified Internal Rate of Return',
 'PEG — P/E to Growth': 'PEG — Price/Earnings to Growth',
 'Excel: ПС / БС (PV / FV)': 'Excel: ПС / БС (PV — Present Value / FV — Future Value)',
}

EXTRA = [
 (['чист(ый|ого|ому|ым) долг\\w*'], 'Чистый долг (Net Debt)', 'Всё, что компания должна, минус деньги, которые у неё уже есть на счетах. Пример: долг 100 млн, на счетах 30 млн — чистый долг 70 млн. Если денег больше, чем долга, чистый долг отрицательный — это хорошо.'),
 (['оборотн(ый|ого|ому|ым) капитал\\w*'], 'Оборотный капитал (NWC)', 'Деньги, застрявшие в повседневных делах компании: товар на складе плюс то, что должны нам покупатели, минус то, что мы должны поставщикам. Чем больше этих денег «заморожено», тем меньше свободных денег остаётся у компании.'),
 (['дебиторк\\w*', 'дебиторск\\w* задолженност\\w*'], 'Дебиторская задолженность', 'Деньги, которые покупатели ещё не заплатили за товар, уже полученный от компании. Пример: отгрузили товар на 100 тыс. ₽ с оплатой через месяц — эти 100 тыс. ₽ пока «висят» как долг покупателя.'),
 (['кредиторк\\w*', 'кредиторск\\w* задолженност\\w*'], 'Кредиторская задолженность', 'Деньги, которые сама компания должна поставщикам за уже полученный товар. Это как беспроцентный кредит: пока не заплатили, можно пользоваться чужими деньгами бесплатно.'),
 (['амортизаци\\w*'], 'Амортизация (D&A)', 'Постепенное «списание» стоимости оборудования и других долгих покупок. Пример: станок за 1 млн, служит 10 лет — каждый год в расходы идёт 100 тыс. ₽, хотя деньги реально потратили один раз. Из-за этого прибыль и налог меньше, а деньги в кассе остаются.'),
 (['выручк\\w*'], 'Выручка (Revenue)', 'Все деньги, которые компания заработала продажами за период, до вычета расходов (без налога НДС). Это самая первая, «верхняя» строка отчёта о прибылях и убытках.'),
 (['себестоимост\\w*'], 'Себестоимость (COGS)', 'Сколько стоило сделать то, что компания продала: сырьё, зарплата рабочих на производстве, электричество. Пример: продали куртку за 5 000 ₽, на её пошив ушло 3 000 ₽ — себестоимость 3 000 ₽.'),
 (['чист(ая|ой|ую) прибыл\\w*'], 'Чистая прибыль (Net Income)', 'Сколько остаётся у компании после вычета всех расходов, процентов по долгам и налогов. Эта прибыль принадлежит владельцам (акционерам), из неё им выплачивают дивиденды.'),
 (['(?<!тонкой )(?<!Тонкой )капитализаци\\w*'], 'Рыночная капитализация', 'Сколько стоит вся компания на бирже: цена одной акции, умноженная на число акций. Пример: акция 100 ₽, акций 1 млн — компания стоит 100 млн ₽.'),
 (['дисконтировани\\w*', 'дисконтир\\w+'], 'Дисконтирование', 'Пересчёт будущих денег в сегодняшние: 100 ₽ через год стоят меньше, чем 100 ₽ сейчас, ведь сегодняшние можно вложить и заработать. Пример: при ставке 10% 110 ₽ через год равны 100 ₽ сегодня. Чем дальше срок и выше ставка, тем дешевле будущие деньги.'),
 (['ставк\\w* дисконтирования'], 'Ставка дисконтирования', 'Процент в год, который инвестор хочет получать за риск вложения. Чем рискованнее, тем он выше. Для всей компании это WACC (средняя цена всех денег компании), для владельцев — Ke (доходность, которую ждут акционеры).'),
 (['терминальн\\w* стоимост\\w*', 'постпрогнозн\\w* стоимост\\w*'], 'Терминальная стоимость (TV)', 'Оценка всего, что компания заработает после последнего года прогноза (обычно прогноз рисуют на 5–10 лет). Считают по формуле Гордона или через мультипликатор выхода (во сколько раз прибыль обычно оценивают при продаже). Часто это 60–80% всей оценки компании.'),
 (['модел\\w* Гордона', 'формул\\w* Гордона'], 'Модель Гордона', 'Формула, которая оценивает бесконечный поток денег, растущий каждый год на одну и ту же долю g: первый платёж делим на (r − g), где r — требуемая доходность. Пример: платёж 10, r = 15%, g = 5% дают 10 / 0,10 = 100. Работает, только если r больше g.'),
 (['бет(а|ы|у|ой)(?![а-я])'], 'Бета (β)', 'Показывает, насколько акция «качается» вместе с рынком. Бета = 1 — движется как рынок, 1,5 — в полтора раза сильнее (и вверх, и вниз), меньше 1 — спокойнее рынка.'),
 (['премия за риск', 'премии за риск'], 'Премия за риск (ERP)', 'Дополнительная доходность, которую инвесторы ждут от акций сверх безопасных вложений (например, гособлигаций) — плата за риск. В США около 3,7% (Дамодаран, сентябрь 2026).'),
 (['безрисков\\w* ставк\\w*'], 'Безрисковая ставка (Rf)', 'Доходность самого надёжного вложения — государственных облигаций в той же валюте и на тот же срок. В России это ОФЗ на 10 лет (около 16,6% в октябре 2026), в США — казначейские облигации на 10 лет (около 5,2%).'),
 (['стоимост\\w* собственного капитала'], 'Стоимость собственного капитала (Ke)', 'Сколько процентов в год хотят получать владельцы компании за риск вложения в её акции. Обычно считают по формуле CAPM: безопасная ставка + бета × премия за риск (Rf + β × ERP).'),
 (['стоимост\\w* долга'], 'Стоимость долга (Kd)', 'Процент, под который компания берёт в долг. В расчётах берут его после налога: Kd × (1 − t), где t — ставка налога, потому что проценты по долгу уменьшают налог. Пример: 20% при налоге 25% дают 15%.'),
 (['налогов\\w* щит\\w*'], 'Налоговый щит', 'Экономия на налоге благодаря тому, что проценты по долгу вычитаются из налогооблагаемой прибыли. Пример: проценты 100 тыс. ₽, налог 25% — компания экономит 25 тыс. ₽. Поэтому долг для компании чуть дешевле, чем кажется.'),
 (['мультипликатор\\w*'], 'Мультипликатор', 'Во сколько раз цена компании больше её показателя: прибыли, выручки и т. д. (примеры: P/E, EV/EBITDA). Пример: компания стоит 700 млн, прибыль 100 млн — мультипликатор 7, то есть рынок платит 7 ₽ за каждый рубль прибыли.'),
 (['премия за контроль', 'премии за контроль', 'премию за контроль'], 'Премия за контроль', 'Наценка сверх биржевой цены, которую покупатель платит, чтобы получить контроль над компанией: право решать, как ею управлять. Обычно 20–40%. Пример: акция стоит 100 ₽ — покупатель готов заплатить 130 ₽.'),
 (['синерги\\w*'], 'Синергии', 'Эффект «1 + 1 = 3»: после объединения двух компаний вместе они зарабатывают больше или тратят меньше, чем по отдельности. Пример: слили две бухгалтерии и сэкономили на зарплатах.'),
 (['гудвил\\w*'], 'Гудвил (Goodwill)', 'Сколько покупатель переплатил за компанию сверх стоимости её реального имущества (за вычетом долгов). Пример: имущество стоит 80 млн, купили за 100 млн — гудвил 20 млн (за бренд, клиентов, команду). Раз в год проверяют, не обесценился ли он.'),
 (['дол(я|и|ю) меньшинства', 'доли меньшинства', 'неконтролирующ\\w* дол\\w*'], 'Доли меньшинства (NCI)', 'Часть дочерней компании, которая принадлежит не нам, а другим владельцам. Пример: мы владеем 80% дочки — остальные 20% это доля меньшинства. Когда считаем стоимость акций материнской компании, эту часть вычитают.'),
 (['дюраци\\w*'], 'Дюрация', 'Показатель в годах: через сколько в среднем вы получите свои деньги назад по облигации. Чем больше дюрация, тем сильнее цена облигации реагирует на ставки: при дюрации 5 рост ставок на 1 п.п. (процентный пункт, например с 14% до 15%) снизит цену примерно на 5%.'),
 (['доходност\\w* к погашению'], 'Доходность к погашению (YTM)', 'Сколько процентов в год вы заработаете, если купите облигацию по сегодняшней цене и продержите до дня погашения (когда вам вернут номинал). Это удобный способ сравнить разные облигации между собой.'),
 (['купон\\w*'], 'Купон', 'Регулярная выплата процентов по облигации, обычно считается от её номинала. Пример: облигация номиналом 1 000 ₽ с купоном 10% в год приносит 100 ₽ в год.'),
 (['номинал(а|ом|у|ы|ов)?(?![а-я])'], 'Номинал облигации', 'Сумма, которую выпустивший облигацию вернёт владельцу в день погашения, обычно 1 000 ₽. Цену облигации на бирже указывают в процентах от номинала: цена 95% значит 950 ₽.'),
 (['оферт\\w*'], 'Оферта (по облигации)', 'Дата, когда выпустивший облигацию обязан выкупить её по желанию владельца (или сам может погасить досрочно). Доходность часто считают именно до этой даты, потому что деньги вернутся раньше срока.'),
 (['кредитн\\w* спред\\w*', 'спред\\w*'], 'Спред', 'Разница между двумя ставками доходности. Кредитный спред — это разница между доходностью облигации компании и ОФЗ (гособлигаций) того же срока: надбавка за то, что компания может не вернуть долг. Пример: 18% − 15% = спред 3 п.п.'),
 (['ковенант\\w*'], 'Ковенант', 'Условие в кредитном договоре или в условиях облигации, которое компания обязана соблюдать. Пример: долг не должен превышать прибыль (EBITDA) более чем в 3 раза. Если нарушила, кредитор вправе потребовать вернуть деньги досрочно.'),
 (['ключев\\w* ставк\\w*'], 'Ключевая ставка', 'Главная ставка Банка России (ЦБ): под этот процент он даёт деньги банкам и принимает у них вклады. От неё зависят ставки по вкладам, кредитам и облигациям во всей стране. Сейчас 14% (с 27.07.2026).'),
 (['кривая доходности', 'кривой доходности', 'кривую доходности'], 'Кривая доходности', 'График, который показывает, сколько процентов платят по гособлигациям на разные сроки. Обычно чем дольше срок, тем выше процент — это норма. Если короткие ставки выше длинных (инвертированная кривая), рынок ждёт, что ставки снизятся.'),
 (['дивидендн\\w* доходност\\w*'], 'Дивидендная доходность', 'Сколько процентов в год составляют дивиденды (выплаты владельцам) от цены акции. Пример: дивиденд 10 ₽ в год, акция стоит 100 ₽ — доходность 10%.'),
 (['байбэк\\w*', 'обратн\\w* выкуп\\w*'], 'Байбэк (buyback)', 'Компания покупает на бирже собственные акции. Это ещё один способ вернуть деньги владельцам, как дивиденды. Акций становится меньше, поэтому прибыль на одну акцию (EPS) растёт.'),
 (['волатильност\\w*'], 'Волатильность (σ)', 'Насколько сильно и часто скачет цена актива. Измеряют в % за год: чем больше число, тем рискованнее актив. Пример: волатильность 30% — цена в течение года обычно отклоняется от среднего примерно на треть.'),
 (['ликвидност\\w*'], 'Ликвидность', 'Насколько быстро и без потери в цене актив можно превратить в деньги. Наличные — самые ликвидные, квартиру продать сложнее. Для компании это ещё и способность вовремя платить по срочным долгам.'),
 (['инфляци\\w*'], 'Инфляция (π)', 'Рост цен в стране: на те же деньги со временем можно купить меньше. В России в сентябре 2026 цены выросли на 6,35% за год, цель ЦБ — 4%.'),
 (['опцион\\w*'], 'Опцион', 'Договор, который даёт право (но не обязывает) купить или продать актив по заранее оговорённой цене до определённой даты. Право купить — колл, право продать — пут. Пример: колл на акцию по 100 ₽ выгоден, если акция подорожает до 120 ₽.'),
 (['фьючерс\\w*', 'форвард\\w*'], 'Форвард / фьючерс', 'Договор купить или продать что-то в будущем по цене, которую согласовали сегодня. Форвард — частная договорённость, фьючерс — такой же договор, но стандартный и торгуется на бирже.'),
 (['стейблкоин\\w*'], 'Стейблкоин', 'Криптовалюта, цена которой привязана к обычной валюте, чаще к доллару (USDT, USDC), поэтому не скачет, как биткоин. Её выпускает компания, которая держит резервы в обеспечение.'),
 (['МСФО'], 'МСФО (IFRS)', 'Международные стандарты финансовой отчётности (на английском IFRS): единые правила, по которым компании составляют отчёты. По ним удобно сравнивать публичные компании, то есть те, чьи акции торгуются на бирже.'),
 (['маржинальност\\w*', 'марж(а|и|у|ой)(?![а-я])'], 'Маржа', 'Какая доля выручки превращается в прибыль. Пример: выручка 100 ₽, прибыль 15 ₽ — маржа 15%. Бывает валовая (после себестоимости), по EBITDA и чистая (после всех расходов и налогов).'),
 (['ОФЗ'], 'ОФЗ', 'Облигации федерального займа — долговые бумаги, которые выпускает государство России. ОФЗ-ПД платят постоянный купон, ОФЗ-ПК — плавающий (зависит от ставки), у ОФЗ-ИН растёт номинал вместе с инфляцией.'),
 (['КБД'], 'КБД (кривая бескупонной доходности)', 'Кривая бескупонной доходности: график, который строят ЦБ и Мосбиржа и который показывает, сколько процентов приносят ОФЗ на разные сроки. По нему определяют безопасную ставку и считают надбавки за риск (спреды).'),
 (['free float', 'фрифлоат\\w*'], 'Free float', 'Доля акций, которые свободно покупают и продают на бирже, то есть которые не принадлежат главным владельцам компании. Чем она больше, тем проще купить или продать акции.'),
 (['IMOEX', 'индекс\\w* Мосбиржи', 'индекс\\w* МосБиржи'], 'Индекс Мосбиржи (IMOEX)', 'Главный показатель российского рынка акций в рублях. Он считается по 40–50 крупнейшим компаниям, которые легко купить и продать; чем компания дороже на бирже и чем больше её акций в свободном обращении (free float), тем сильнее она влияет на индекс. Если индекс растёт, акции в среднем дорожают.'),
 (['S&P 500'], 'S&P 500', 'Индекс 500 крупнейших американских компаний. По нему смотрят, как в целом дела на рынке акций США: если индекс растёт, акции в среднем дорожают.'),
 (['Дамодаран\\w*'], 'Асват Дамодаран', 'Профессор Нью-Йоркского университета (NYU Stern), самый известный специалист по оценке компаний. Бесплатно публикует нужные данные: премию за риск, беты и мультипликаторы по отраслям и странам.'),
]

RICH = [
 (['NPV'], 'NPV — чистая приведённая стоимость', 'Сумма всех будущих денег от проекта, пересчитанных в сегодняшние (с учётом того, что деньги в будущем дешевле), минус вложенные сейчас деньги. Если число больше нуля, проект приносит пользу. Excel: =ЧПС(r;потоки)+инвестиция.'),
 (['IRR'], 'IRR — внутренняя норма доходности', 'Годовая доходность проекта: ставка, при которой NPV (польза проекта в сегодняшних деньгах) равна нулю. Если она выше WACC (средней цены денег компании), проект стоит делать. Excel: =ВСД(потоки).'),
 (['WACC'], 'WACC — средневзвешенная стоимость капитала', 'Средняя цена денег компании: смесь того, что хотят получать владельцы (Ke) и кредиторы (Kd после налога), с учётом долей. Формула: E/(D+E)×Ke + D/(D+E)×Kd×(1−t), где E — деньги владельцев, D — долг. Для российских компаний сейчас обычно 17–22%.'),
 (['EBITDA'], 'EBITDA', 'Прибыль до вычета процентов, налогов и амортизации (EBIT + амортизация). Грубо показывает, сколько денег приносит основная работа компании. На неё опираются мультипликаторы EV/EBITDA и ND/EBITDA (чистый долг к EBITDA). Для банков не подходит.'),
 (['EBIT'], 'EBIT', 'Операционная прибыль: что остаётся от выручки после себестоимости, остальных расходов и амортизации, но до процентов по долгам и налогов. Показывает, насколько прибылен сам бизнес.'),
 (['EV'], 'EV — стоимость бизнеса (Enterprise Value)', 'Стоимость всего бизнеса для всех, кто в него вложил деньги (и владельцев, и кредиторов). Считают так: капитализация + долг − деньги на счетах + доли меньшинства (+ префы, аренда) − ассоциированные. Пример: капитализация 100, долг 40, деньги 10 — EV = 130.'),
 (['DCF'], 'DCF — дисконтированные денежные потоки', 'Способ оценить компанию: прогнозируем, сколько свободных денег она принесёт в будущем, пересчитываем их в сегодняшние по ставке WACC (средней цене денег компании) и прибавляем оценку всего, что будет после прогноза (терминальную стоимость).'),
 (['CAPM'], 'CAPM — модель ценообразования активов', 'Формула для расчёта доходности, которую ждут владельцы акций: Ke = Rf + β × ERP, то есть безопасная ставка плюс бета (насколько акция «качается» вместе с рынком) умноженная на премию за риск рынка. Пример: 16% + 1,2 × 5% = 22%.'),
 (['EVA'], 'EVA — экономическая добавленная стоимость', 'Показывает, создаёт ли компания стоимость: (ROIC − WACC) × вложенный капитал. ROIC — сколько прибыли приносит каждый вложенный рубль, WACC — сколько этот рубль стоит компании. Если EVA больше нуля, компания зарабатывает больше, чем стоят деньги в ней. Для банков не подходит.'),
 (['CAPEX'], 'CAPEX — капитальные затраты', 'Деньги, потраченные на покупку или строительство долгих вещей: станков, зданий, оборудования. Эти траты вычитают, когда считают свободные деньги компании (FCF).'),
 (['LBO'], 'LBO — выкуп с плечом', 'Покупка компании инвестиционным фондом в основном на заёмные деньги (плечо), которые потом гасят деньгами самой купленной компании. Цель фонда — доходность (IRR) 20–25% в год.'),
 (['M&A'], 'M&A — слияния и поглощения', 'Слияния и поглощения: сделки, когда компании покупают, продают или объединяют. Банк помогает либо продавцу (sell-side), либо покупателю (buy-side).'),
 (['P/E'], 'P/E — цена / прибыль', 'Во сколько раз цена компании больше её годовой чистой прибыли (капитализация / чистая прибыль). Показывает, за сколько лет прибыли окупится покупка. Пример: P/E 7 — 7 лет. В России около 7 (медиана, то есть типичное значение), в S&P 500 около 26.'),
 (['ROE'], 'ROE — рентабельность капитала', 'Рентабельность капитала: сколько чистой прибыли приносит каждый рубль владельцев (чистая прибыль / собственный капитал). Пример: прибыль 20, капитал 100 — ROE 20%. Если ROE выше Ke (доходности, которую ждут владельцы), компания должна стоить дороже своей балансовой стоимости (P/B больше 1) — особенно банк.'),
 (['ERP'], 'ERP — премия за риск акций', 'Сколько дополнительных процентов в год ждут от акций по сравнению с самым надёжным вложением (гособлигациями). В США 3,7% (Дамодаран, сент. 2026); в рублях брокеры закладывают 5–8%.'),
]

def glossary_terms(md):
    out = []
    for line in md.split('\n'):
        if not line.startswith('| **'): continue
        cells = [c.strip() for c in line.strip('|').split('|')]
        term = cells[0].replace('**', '').strip()
        exp, mean = cells[1], cells[2]
        title = term + (' — ' + exp if exp else '')
        aliases = re.split(r'\s+/\s+|,\s*', term)
        aliases = [a.strip() for a in aliases if a.strip()]
        # «Synergies», «Teaser» и т.п. — английские слова в тексте почти не встречаются; оставляем
        pats = []
        for a in aliases:
            if re.match(r'^[A-Za-zА-ЯЁ&/()0-9 .-]+$', a):
                pats.append(re.escape(a).replace('\\ ', ' '))
        if pats:
            out.append((pats, title, mean))
    return out

def build(glossary_md):
    seen = set(); terms = []
    for pats, title, d in RICH + EXTRA + glossary_terms(glossary_md):
        key = pats[0].lower()
        if key in seen: continue
        seen.add(key)
        terms.append({'p': pats, 't': enrich(title, OVR), 'd': d})
    import json, os
    mp = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'terms_more.json')
    if os.path.exists(mp):
        for e in json.load(open(mp, encoding='utf-8')):
            key = e['p'][0].lower()
            if key in seen: continue
            seen.add(key)
            terms.append({'p': [re.escape(x) for x in e['p']], 't': e['t'], 'd': e['d']})
    return terms
